// ✅ STRUCT (Value Type - Copies the data)
struct Point { public int X; }

Point p1 = new Point { X = 5 };
Point p2 = p1;       // Creates a BRAND NEW copy!
p2.X = 10;           // Changing the copy...

Console.WriteLine(p1.X); // Output: 5 (The original is safe!)


// ❌ CLASS (Reference Type - Shares the data)
class Player { public int Health; }

Player player1 = new Player { Health = 100 };
Player player2 = player1; // They both point to the SAME player!
player2.Health = 0;       // Changing player 2...

Console.WriteLine(player1.Health); // Output: 0 (The original is dead!)

// ── ABSTRACT CLASS (Shares real code) ──
abstract class Vehicle {
    public int Fuel = 100; // Real state!

    // Real method that all vehicles share
    public void StartEngine() => Console.WriteLine("Vroom!");

    // Blank method that the child MUST write
    public abstract void Move(); 
}

class Car : Vehicle {
    public override void Move() => Console.WriteLine("Driving on road");
}

// ── INTERFACE (Just a contract) ──
interface IFlyable {
    void Fly(); // No code allowed here!
}

interface ISwimmable {
    void Swim();
}

// We can use MULTIPLE interfaces!
class Duck : IFlyable, ISwimmable {
    public void Fly() => Console.WriteLine("Flap flap");
    public void Swim() => Console.WriteLine("Paddle paddle");
}

