// ❌ THE BAD WAY (IEnumerable)
// By adding .ToList() early, we force EF Core to download the entire table!
IEnumerable<User> users = db.Users.ToList(); 

// This filtering happens in our app's RAM, which is very slow.
var admins = users.Where(u => u.Role == "Admin");


// ✅ THE GOOD WAY (IQueryable)
// Notice we DO NOT use .ToList() yet.
IQueryable<User> query = db.Users.AsQueryable();

// This doesn't run yet. It just builds a SQL command.
var adminsQuery = query.Where(u => u.Role == "Admin");

// Calling .ToList() finally sends the optimized SQL to the database!
// SQL Sent: SELECT * FROM Users WHERE Role = 'Admin'
var adminsList = adminsQuery.ToList();

// ✅ THE ASYNC WAY (Non-blocking)
public async Task<string> GetUserDataAsync() {
    Console.WriteLine("1. Sending request to database...");

    // The 'await' keyword pauses this method.
    // The thread leaves this method to go do other work!
    var data = await db.Users.ToListAsync(); 

    // 2 seconds later, the database finishes.
    // A thread comes back to finish the rest of this method.
    Console.WriteLine("2. Got the data!");
    return data;
}

// ❌ THE DEADLOCK MISTAKE
public string BadCode() {
    // NEVER call .Result on an async method in ASP.NET or UI apps.
    // It forces the thread to wait, which can freeze your entire app!
    return GetUserDataAsync().Result; 
}

// ── REF (Variable MUST have a value first) ──
void DoubleIt(ref int number) {
    number = number * 2; 
}

int myNum = 5;       // MUST initialize!
DoubleIt(ref myNum);
Console.WriteLine(myNum); // Output: 10


// ── OUT (Method MUST assign a value) ──
// Returns true/false, AND outputs the answer
bool TryDivide(int a, int b, out int answer) {
    if (b == 0) {
        answer = 0;   // MUST assign a value before returning
        return false;
    }
    answer = a / b;   // MUST assign a value before returning
    return true;
}

// You don't need to initialize 'result' first!
if (TryDivide(10, 2, out int result)) {
    Console.WriteLine($"Success! Answer is {result}");
}

