// ❌ THE BAD WAY (Causes Boxing!)
// ArrayList stores "objects", not ints. 
// Every single number gets locked in a heavy box!
ArrayList badList = new ArrayList();
badList.Add(5);  // Boxing happens secretly here!
badList.Add(10); // Boxing happens again!

// To get the number out, we have to Unbox it:
int myNumber = (int)badList[0]; 


// ✅ THE GOOD WAY (Generics = No Boxing!)
// List<int> specifically stores ints. No boxes allowed!
List<int> goodList = new List<int>();
goodList.Add(5);  // Fast! Just stays on the stack.
goodList.Add(10); // Fast!

int myNumber2 = goodList[0]; // Fast! No casting needed.

// 1. Create a class that PUBLISHES an event (The YouTuber)
public class VideoUploader {
    // This is the Event (The 'Action' delegate means it takes no parameters)
    public event Action OnVideoUploaded;

    public void Upload() {
        Console.WriteLine("Uploading video...");
        // 2. Trigger the event! This notifies everyone who subscribed.
        OnVideoUploaded?.Invoke(); 
    }
}

// 3. SUBSCRIBING to the event (The Viewers)
var uploader = new VideoUploader();

// Subscriber 1 wants an email
uploader.OnVideoUploaded += () => Console.WriteLine("Email sent!");

// Subscriber 2 wants a text message
uploader.OnVideoUploaded += () => Console.WriteLine("Text sent!");

// 4. Action! 
uploader.Upload(); 
// Output:
// Uploading video...
// Email sent!
// Text sent!

