// 🚀 HOW TO WRITE YOUR OWN GENERIC METHOD
// This method swaps ANY two things. Numbers, strings, objects, anything!
void Swap<T>(ref T a, ref T b) {
    T temp = a;
    a = b;
    b = temp;
}

int x = 1, y = 2;
Swap<int>(ref x, ref y); // Works for ints!

string first = "A", second = "B";
Swap<string>(ref first, ref second); // Works for strings!

class User { public string Name; public int Age; }

var users = new List<User> {
    new User { Name = "Alice", Age = 25 },
    new User { Name = "Bob", Age = 15 },
    new User { Name = "Charlie", Age = 30 }
};

// ❌ THE BAD WAY (Ugly foreach loop)
List<string> adults = new List<string>();
foreach (var user in users) {
    if (user.Age >= 18) {
        adults.Add(user.Name);
    }
}
adults.Sort();


// ✅ THE LINQ WAY (Clean, declarative)
// "Get users where age >= 18, sort by name, and just give me the name string"
var adultNames = users
    .Where(u => u.Age >= 18)    // 1. Filter
    .OrderBy(u => u.Name)       // 2. Sort
    .Select(u => u.Name)        // 3. Extract just the name
    .ToList();                  // 4. EXECUTE!

// output: ["Alice", "Charlie"]

// ✅ CREATING A RECORD (Look how short it is!)
// This 1 line creates a class, properties, and a constructor automatically.
public record UserDto(int Id, string Name);


var u1 = new UserDto(1, "Alice");
var u2 = new UserDto(1, "Alice");

// 1. VALUE EQUALITY
Console.WriteLine(u1 == u2); // Output: TRUE! (Classes would return false here)

// 2. IMMUTABILITY
// u1.Name = "Bob"; // ❌ COMPILER ERROR! Records are read-only.

// 3. THE 'WITH' KEYWORD (Non-destructive mutation)
// Creates a brand new copy, but changes the Name to Bob.
var u3 = u1 with { Name = "Bob" }; 

Console.WriteLine(u3.Name); // Output: Bob

// ❌ THE BAD WAY (Creates 10,000 dead strings in memory!)
