// ── 1. LIST (Ordered, allows duplicates) ──
var list = new List<string> { "Apple", "Apple", "Banana" };
// list[0] == "Apple"
// list.Contains("Banana") -> Slow! Checks every item one by one.


// ── 2. DICTIONARY (Key/Value, instant lookup) ──
var dict = new Dictionary<int, string>();
dict.Add(1, "Alice");
dict.Add(2, "Bob");

string user = dict[1]; // INSTANTLY gets "Alice". No searching required.


// ── 3. HASHSET (Unique items, instant lookup) ──
var set = new HashSet<string>();
set.Add("Apple");
set.Add("Apple"); // Ignored! HashSets physically cannot hold duplicates.

bool hasApple = set.Contains("Apple"); // INSTANTLY returns true. Super fast!

