// ✅ PRODUCER: Streams data slowly over the network
public async IAsyncEnumerable<int> GetNumbersAsync()
{
    for (int i = 0; i < 10; i++)
    {
        await Task.Delay(1000); // Simulate network latency
        yield return i;         // Send 1 item immediately!
    }
}

// ✅ CONSUMER: Processes items as they arrive
public async Task ProcessAsync()
{
    // Notice the 'await foreach' syntax!
    await foreach (var number in GetNumbersAsync())
    {
        Console.WriteLine(number);
    }
}

// Let's say this method is called 50,000 times a second.
public async ValueTask<User> GetUserAsync(int id)
{
    // 99% of the time, the user is in the cache.
    // Because we use ValueTask, this returns synchronously with ZERO heap allocation!
    if (_cache.TryGetValue(id, out var user))
        return user;

    // 1% of the time, we hit the database.
    return await _db.Users.FindAsync(id);
}
